-- TomoModForever 1.2.5 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_125_mana"] = "New - Party frames: every member who uses mana now has a mana bar (before, only members with the healer role, rarely set on Forever), with their mana in % on the health bar: blue, orange under 40%, red under 20%. Healers only or everyone can be chosen.",
    ["wn_125_levels"] = "New - World map: hovering a zone shows its level range, coloured for your level (red too high, orange right for you, green easy, grey too low).",
    ["wn_125_codexbtn"] = "New - Chat sidebar: a book button opens the dungeon codex (/codex).",
    ["wn_125_elites"] = "New - Dungeon codex: an Elites tab lists the zones with elite quests for your faction (270 quests over 42 zones), by level. Each zone shows its elite quests with their level, minimum level and state (done, in your quest log, to take), and opens the zone map. Click a quest for a waypoint to its giver (or to the turn-in when an item starts it).",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_125_mana"] = "Nouveau - Cadres de groupe : chaque membre qui utilise de la mana a maintenant sa barre (avant, seuls les membres au rôle de soigneur, rarement attribué sur Forever), avec sa mana en % sur la barre de vie : bleu, orange sous 40 %, rouge sous 20 %. On peut choisir les soigneurs seulement ou tout le monde.",
    ["wn_125_levels"] = "Nouveau - Carte du monde : au survol d'une zone, sa tranche de niveaux s'affiche, colorée selon ton niveau (rouge trop haut, orange pour toi, vert facile, gris trop bas).",
    ["wn_125_codexbtn"] = "Nouveau - Barre latérale du chat : un bouton livre ouvre le codex des donjons (/codex).",
    ["wn_125_elites"] = "Nouveau - Codex des donjons : un onglet Élites liste les zones qui ont des quêtes élites pour ta faction (270 quêtes dans 42 zones), par niveau. Chaque zone montre ses quêtes élites avec leur niveau, leur niveau minimum et leur état (faite, dans ton journal, à prendre), et ouvre la carte de la zone. Clique sur une quête pour poser un point de route vers son donneur (ou vers l'endroit où la rendre quand un objet la lance).",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_125_mana"] = "Neu - Gruppenrahmen: Jedes Mitglied mit Mana hat jetzt eine Manaleiste (vorher nur Mitglieder mit Heilerrolle, die auf Forever selten vergeben ist), mit seinem Mana in % auf der Lebensleiste: blau, orange unter 40 %, rot unter 20 %. Nur Heiler oder alle sind wählbar.",
    ["wn_125_levels"] = "Neu - Weltkarte: Beim Zeigen auf ein Gebiet erscheint seine Stufenspanne, eingefärbt nach deiner Stufe (rot zu hoch, orange passend, grün leicht, grau zu niedrig).",
    ["wn_125_codexbtn"] = "Neu - Chat-Seitenleiste: Ein Buch-Knopf öffnet den Dungeon-Kodex (/codex).",
    ["wn_125_elites"] = "Neu - Dungeon-Kodex: Ein Reiter Elite listet die Gebiete mit Elitequests für deine Fraktion (270 Quests in 42 Gebieten), nach Stufe. Jedes Gebiet zeigt seine Elitequests mit Stufe, Mindeststufe und Zustand (erledigt, im Questlog, anzunehmen) und öffnet die Gebietskarte. Klicke auf eine Quest für einen Wegpunkt zum Questgeber (oder zur Abgabe, wenn ein Gegenstand sie startet).",
