TomoMod_RegisterLocale("esES", {
    ["wn_125_mana"] = "Nuevo - Marcos de grupo: cada miembro que usa maná tiene ahora su barra (antes solo los miembros con rol de sanador, poco usado en Forever), con su maná en % sobre la barra de vida: azul, naranja por debajo del 40 %, rojo por debajo del 20 %. Se puede elegir solo sanadores o todos.",
    ["wn_125_levels"] = "Nuevo - Mapa del mundo: al pasar sobre una zona se muestra su rango de niveles, coloreado según tu nivel (rojo demasiado alto, naranja para ti, verde fácil, gris demasiado bajo).",
    ["wn_125_codexbtn"] = "Nuevo - Barra lateral del chat: un botón de libro abre el códice de mazmorras (/codex).",
    ["wn_125_elites"] = "Nuevo - Códice de mazmorras: una pestaña Élites muestra las zonas con misiones de élite para tu facción (270 misiones en 42 zonas), por nivel. Cada zona muestra sus misiones de élite con su nivel, nivel mínimo y estado (hecha, en tu registro, por aceptar), y abre el mapa de la zona. Haz clic en una misión para poner un punto de ruta hacia quien la da (o hacia la entrega si la inicia un objeto).",
})

